//! 🧪️ Original admitted fonts remain borrowed across run completion and cancellation.
use super::*;
#[test]fn neutral_run_retirement_preserves_original_font_sources(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let mut admission=FontFaceAdmissionJob::new(bytes("⌨️share-tech-mono/🏛️latin/📖️regular"),FontOutlineLimits::default());while !admission.advance(4096,&mut semio_framework_2d_text_font::work::RetainedWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(4096))).unwrap().done{}let fonts=[admission.take_result().unwrap()];let pointer=fonts[0].source.as_ptr();let mut unicode_job=semio_framework_2d_text_font_shape_unicode::UnicodeDataAdmissionJob::new(semio_framework_2d_text_font_shape_unicode::UNICODE_BYTES.to_vec(),1000000);while !semio_framework_2d_text_font_testing::with_work(4096,|w,e|unicode_job.advance(4096,w,e)).unwrap().done{}let unicode=unicode_job.take_result().unwrap();let text=fixture["text"].as_str().unwrap();for stop in fixture["stops"].as_array().unwrap(){for grant in fixture["grants"].as_array().unwrap(){let grant=grant.as_u64().unwrap()as usize;let style=crate::FontRunStyle{size:11.0,origin:[0.0,0.0],line_height:1.2,kerning:false,outlines:true};let mut cursor=crate::FontOutlineRunCursor::new(text,fonts.len(),style,FontOutlineLimits::default(),unicode.layout,&unicode.source,&[],semio_framework_2d_text_font_shape_unicode::bidi::UnicodeBidiDirection::Auto);if let Some(stop)=stop.as_u64(){if stop!=0{semio_framework_2d_text_font_testing::with_effect(|e|cursor.advance(text,&fonts,&unicode.source,&[],stop as usize,&mut semio_framework_2d_text_font::work::RetainedWorkLedger::new(semio_framework_2d_text_font_testing::work_grant(stop as usize)),e)).unwrap();}cursor.cancel();}else{while !semio_framework_2d_text_font_testing::with_work(grant,|w,e|cursor.advance(text,&fonts,&unicode.source,&[],grant,w,e)).unwrap().done{}}close(cursor);assert_eq!(fonts.len()as u64,fixture["expectedFaces"].as_u64().unwrap());assert_eq!(fonts[0].source.as_ptr(),pointer);assert!(ttf_parser::Face::parse(&fonts[0].source,0).unwrap().number_of_glyphs()>0);}}close(fonts);close(admission);close(unicode);close(unicode_job);}
